var assignEdgeWeights = function(edges) {
    const MOD = 1000000007n;
    const n = edges.length + 1;

    const graph = Array.from({ length: n + 1 }, () => []);
    for (const [u, v] of edges) {
        graph[u].push(v);
        graph[v].push(u);
    }

    const queue = [1];
    const seen = new Array(n + 1).fill(false);
    seen[1] = true;

    let maxDepth = -1;
    let head = 0;

    while (head < queue.length) {
        const sz = queue.length - head;
        for (let i = 0; i < sz; ++i) {
            const u = queue[head++];
            for (const v of graph[u]) {
                if (!seen[v]) {
                    seen[v] = true;
                    queue.push(v);
                }
            }
        }
        maxDepth++;
    }

    if (maxDepth <= 0) return 0;

    function modPow(base, exp) {
        let res = 1n;
        base = BigInt(base) % MOD;
        exp = BigInt(exp);
        while (exp > 0n) {
            if (exp % 2n === 1n) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp /= 2n;
        }
        return res;
    }

    return Number(modPow(2n, BigInt(maxDepth - 1)));
};
